// PENDING_PAYMENT は課金されたか分からない。照合バッチが
// PAID か PAYMENT_FAILED に決めるまで待ってもらう（default で 409）

function parseFeePercent(raw: string | undefined): number {
  if (raw === undefined || raw === '') return 10;
  const n = Number(raw);
  if (!Number.isInteger(n) || n < 0 || n > 100) {
    throw new Error(`CANCELLATION_FEE_PERCENT must be 0-100: ${raw}`);
  }
  return n;
}
